// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: deployer = address(this) is proposer and executor (via address(this) in constructor)
        // But for the test we need a scenario where the reference passes and bug fails
        // The difference: supportsInterface always returns true in M.
        // Use a scenario where supportsInterface is not called by the contract itself.
        // The bug changes only supportsInterface, which is not used by cancel or execute...
        // Wait, the instruction says the difference is about a call to supportsInterface that completes in both but returns different values.
        // To observe this, we just call supportsInterface with some interfaceId and assert the return.
        // The reference returns true for IAccessControl and ERC165, false for others; bug always true.
        // Choose an interfaceId that is not supported by reference, e.g., 0xffffffff.
        bytes32 id = c.hashOperation(address(0xdead), 0, "", bytes32(0), bytes32(0));
        // schedule a minimal operation (no target call needed for the test)
        vm.warp(1000);
        c.schedule(address(0xdead), 0, "", bytes32(0), bytes32(0), 1);
        // Now call cancel to make operation pending and then cancel
        c.cancel(id);
        // After cancellation, operation should not be pending
        bool result;
        result = c.supportsInterface(0xffffffff);
        // True for M (bug), false for P (reference)
        assertTrue(result, "supportsInterface should return false for unknown interface");
    }
}

