pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: schedule an operation as proposer (address(this) is proposer by default)
        address target = address(0x123);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Now try to cancel with a non-proposer account (address(0x456))
        address nonProposer = address(0x456);
        vm.prank(nonProposer);
        bool cancelReverted;
        try c.cancel(id) {
            cancelReverted = false;
        } catch {
            cancelReverted = true;
        }

        // Assert: in reference, cancel reverts (true); in buggy, cancel succeeds and operation becomes pending = false
        // Check that after the call, the operation is still pending in the reference (cancel failed) but not pending in buggy (cancel succeeded)
        bool pendingAfter = c.isOperationPending(id);
        assertTrue(cancelReverted == true && pendingAfter == true);
    }
}

