        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = keccak256("test");
        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Now call cancel from an address that is NOT a proposer (e.g., address(0x1234))
        vm.prank(address(0x1234));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));

        // In the reference, cancel reverts because 0x1234 is not a proposer => ok false
        // In the buggy version, hasRole returns true for 0x1234 to check PROPOSER_ROLE, so cancel succeeds => ok true
        // After successful cancel, the operation is no longer pending.
        // Assert that in our test (using reference), the cancel reverts (ok == false)
        assertTrue(!ok, "cancel should revert for non-proposer");
    }
}

