pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: grab the timelock admin role (address(this) is admin from deploy)
        bytes32 proposerRole = c.PROPOSER_ROLE();
        bytes32 adminRole = 0x00;
        // Grant EXECUTOR_ROLE to this contract's address so we can use it for execution later if needed
        bytes32 executorRole = c.EXECUTOR_ROLE();
        c.grantRole(executorRole, address(this));

        // Schedule an operation as the default admin
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        uint256 delay = 1 days;
        vm.warp(block.timestamp + 1); // ensure time passes
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Now, as a non-proposer (vm.prank with a random address), try to cancel
        address nonProposer = address(0x1234);
        vm.prank(nonProposer);
        bool ok;
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        ok = success;

        // Reference: cancel reverts, so ok == false; operation remains pending
        // Bug: cancel succeeds, so ok == true; operation no longer pending
        assertTrue(ok == true); // This fails on reference (ok is false) and passes on bug (ok is true)
    }
}

