pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: deployer has TIMELOCK_ADMIN_ROLE, can schedule
        bytes32 PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
        bytes32 EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

        // Grant PROPOSER_ROLE to address(this) so we can schedule and cancel
        c.grantRole(PROPOSER_ROLE, address(this));

        // Schedule an operation
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        uint256 delay = 1 days;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Get the operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Now call cancel - in reference, it succeeds; in buggy, getRoleAdmin returns 0x00 causing revert in grantRole
        // The cancel function uses onlyRole(PROPOSER_ROLE) which calls _checkRole, but no difference there.
        // Actually the difference is exposed via the internal _setRoleAdmin / grantRole chain?
        // Let's pick a different scenario: use the fact that getRoleAdmin(0x00) differs.
        // Grant EXECUTOR_ROLE to address(this) to test execute later
        c.grantRole(EXECUTOR_ROLE, address(this));

        // Renounce EXECUTOR_ROLE
        c.renounceRole(EXECUTOR_ROLE, address(this));

        // Now try to grant EXECUTOR_ROLE again - in reference, getRoleAdmin(EXECUTOR_ROLE) returns TIMELOCK_ADMIN_ROLE
        // which address(this) has, so grantRole succeeds. In buggy, getRoleAdmin(EXECUTOR_ROLE) returns 0x00,
        // and address(this) does NOT have DEFAULT_ADMIN_ROLE (0x00), so grantRole reverts.

        bool ok;
        try c.grantRole(EXECUTOR_ROLE, address(this)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok == true; Buggy: ok == false
        assertTrue(ok);
    }
}

